package io.translab.tantor.server.service;

import com.fasterxml.jackson.databind.ObjectMapper;
import io.translab.tantor.server.config.*;
import io.translab.tantor.server.domain.*;
import io.translab.tantor.server.dto.AddNodeReadiness.*;
import io.translab.tantor.server.repository.*;
import org.junit.jupiter.api.Test;
import java.time.Instant;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

class KafkaExpansionPlanCollectorTest {
    final ControllerAdditionPlanningService controllers=mock(ControllerAdditionPlanningService.class);final AddNodeReadinessService readiness=mock(AddNodeReadinessService.class);final KafkaExpansionRuntimeInspection runtime=mock(KafkaExpansionRuntimeInspection.class);final KafkaExpansionQuorum quorum=mock(KafkaExpansionQuorum.class);final BrokerAdditionKafka brokerKafka=mock(BrokerAdditionKafka.class);final ClusterRepository clusters=mock(ClusterRepository.class);final HostRepository hosts=mock(HostRepository.class);final TaskRepository tasks=mock(TaskRepository.class);final ObjectMapper mapper=new ObjectMapper().findAndRegisterModules();final KafkaExpansionProperties policy=new KafkaExpansionProperties();
    final KafkaExpansionPlanCollector collector=new KafkaExpansionPlanCollector(controllers,readiness,runtime,quorum,brokerKafka,clusters,hosts,tasks,new AddNodeReadinessProperties(),policy,new KafkaDeploymentProperties(),new ArtifactRepositoryProperties(),new AddNodeInspectionProperties(),mock(AddNodeArtifactCatalog.class),mapper);
    KafkaExpansionPlan p;UUID previewId=UUID.randomUUID();List<UUID> runtimeIds=new ArrayList<>();Preview common;ControllerAdditionPlanningService.Review review;Instant expiry=Instant.now().plusSeconds(120);
    void fixture()throws Exception{
        p=new KafkaExpansionPlanTest().plan();var cluster=new Cluster();cluster.setId(p.clusterId());cluster.setKafkaClusterId(p.kafkaClusterId());cluster.setKafkaVersion(p.kafkaVersion());cluster.setNodeIds(List.of(1,101));cluster.setServices(new ArrayList<>());for(var member:p.participants()){var assignment=new ClusterServiceAssignment();assignment.setNodeId(member.nodeId());assignment.setRole(member.role());cluster.getServices().add(assignment);}
        when(clusters.findWithServicesById(p.clusterId())).thenReturn(Optional.of(cluster));var candidate=new Host();candidate.setId(p.candidateHostId());candidate.setHostIp(p.candidateIp());candidate.setAgentVersion("test-addnode.7");when(hosts.findById(candidate.getId())).thenReturn(Optional.of(candidate));
        review=mock(ControllerAdditionPlanningService.Review.class);when(controllers.review(p.clusterId(),p.candidateHostId())).thenReturn(review);when(review.quorumMode()).thenReturn("DYNAMIC");when(review.proposedControllerId()).thenReturn(102);when(review.kafkaVersion()).thenReturn(p.kafkaVersion());when(review.kafkaClusterId()).thenReturn(p.kafkaClusterId());when(review.artifactId()).thenReturn(p.artifactId().toString());when(review.artifactChecksum()).thenReturn(p.artifactSha256());when(review.contextHash()).thenReturn("a".repeat(64));when(review.observedNodeIds()).thenReturn(List.of(1,101));when(review.controllerEndpoints()).thenReturn(List.of("192.0.2.2:9093"));
        var inventory=new ArrayList<ControllerAdditionPlanningService.Participant>();
        for(var member:p.participants()){
            var host=new Host();host.setId(member.hostId());host.setHostIp(member.hostIp());when(hosts.findById(host.getId())).thenReturn(Optional.of(host));UUID taskId=UUID.randomUUID(),serviceId=member.serviceIds().getFirst();runtimeIds.add(taskId);inventory.add(new ControllerAdditionPlanningService.Participant(member.hostId(),member.role(),member.nodeId(),member.unit(),member.configPath(),"OBSERVED",serviceId,true,true));
            var metadata=member.storage().stream().map(s->new AddNodeProcessInspectionService.Metadata(s.path(),p.kafkaClusterId(),member.nodeId(),s.directoryId())).toList();
            var identity=new AddNodeProcessInspectionService.Evidence("add-node-process/v1",UUID.randomUUID(),member.hostId(),"a".repeat(64),p.kafkaClusterId(),p.kafkaVersion(),member.nodeId(),member.role(),member.unit(),member.configPath(),member.configSha256(),member.unitSha256(),member.pid(),member.startTicks(),true,metadata,true,false,false,Instant.now(),List.of());
            var proof=new KafkaExpansionRuntimeInspection.RuntimeProof("add-node-runtime/v1",p.artifactSha256(),p.kafkaVersion(),member.runtimeHome(),"a".repeat(64),member.artifactProofSha256(),107);var report=new KafkaExpansionRuntimeInspection.Report("add-node-runtime-inspection/v1",identity,proof,Map.of(),Map.of(),Map.of("num.network.threads","3"),member.controllerPort(),Instant.now());
            when(runtime.get(p.clusterId(),taskId)).thenReturn(new KafkaExpansionRuntimeInspection.View(taskId,serviceId,member.hostId(),"OBSERVED",expiry,report,false,"Verified"));
        }
        when(review.participants()).thenReturn(inventory);var voters=new HashMap<Integer,KafkaExpansionQuorum.Replica>();p.voters().forEach(v->voters.put(v.nodeId(),new KafkaExpansionQuorum.Replica(v.nodeId(),v.directoryId(),100,Instant.now().toEpochMilli())));when(quorum.observe(any())).thenReturn(new KafkaExpansionQuorum.Snapshot(p.kafkaClusterId(),p.features(),101,100,voters,Map.of(),Map.of(),Instant.now()));
        var profile=new HashMap<String,Object>();profile.put("brokerRack","");profile.put("parcelDir",p.parcelDir());profile.put("javaHome",p.javaHome());profile.put("runtimeUser",p.runtimeUser());profile.put("securityMode","PLAINTEXT");profile.put("kafkaClusterId",p.kafkaClusterId());profile.put("kafkaVersion",p.kafkaVersion());profile.put("hostIp",p.candidateIp());profile.put("brokerPort","9092");profile.put("artifactChecksum",p.artifactSha256());profile.put("dataPaths",List.of("/data/broker"));profile.put("metadataPath","/data/broker-meta");profile.put("logPath","/var/log/new-broker");profile.put("installPath","/opt/kafka");profile.put("heapXmx","1g");profile.put("quorumMode","DYNAMIC");profile.put("controllerEndpoints",List.of("192.0.2.2:9093"));
        var checks=new ArrayList<Check>();for(String phase:List.of("COMMON","BROKER"))for(int i=1;i<=(phase.equals("COMMON")?21:11);i++)checks.add(new Check((phase.equals("COMMON")?"C":"B")+String.format("%02d",i),"check",phase,"PASS","ok","ok","",Instant.now(),"AGENT"));common=new Preview(previewId,p.clusterId(),p.candidateHostId(),"a".repeat(64),Instant.now(),expiry,"PASS",checks,profile,false);when(readiness.get(p.clusterId(),previewId)).thenAnswer(call->common);
        var task=new Task();task.setClusterId(p.clusterId());task.setHostId(p.candidateHostId());task.setCommand(AddNodeReadinessService.COMMAND);task.setParameters(mapper.writeValueAsString(Map.of("readiness_request",mapper.writeValueAsString(profile))));when(tasks.findById(previewId)).thenReturn(Optional.of(task));when(brokerKafka.properties(any(),any())).thenReturn("num.network.threads=3\n");
    }
    KafkaExpansionPlanCollector.Request request(KafkaExpansionWorkflow.Layout layout){return new KafkaExpansionPlanCollector.Request(p.candidateHostId(),layout,previewId,runtimeIds,"",false);}
    @Test void collectorFreezesBothSupportedLayoutsFromReferenceEvidenceOnly()throws Exception{fixture();for(var layout:KafkaExpansionWorkflow.Layout.values()){var result=collector.collect(p.clusterId(),UUID.randomUUID(),request(layout));assertEquals(layout,result.frozen().plan().layout());assertEquals(102,result.frozen().plan().process("controller").nodeId());if(layout==KafkaExpansionWorkflow.Layout.SEPARATE)assertEquals(2,result.frozen().plan().process("broker").nodeId());assertEquals(2,result.frozen().plan().participants().size());}verify(tasks,never()).saveAndFlush(any());}
    @Test void missingParticipantAndUnacknowledgedStaticDowntimeAreRejected()throws Exception{fixture();runtimeIds.removeLast();assertThrows(org.springframework.web.server.ResponseStatusException.class,()->collector.collect(p.clusterId(),UUID.randomUUID(),request(KafkaExpansionWorkflow.Layout.CONTROLLER)));when(review.quorumMode()).thenReturn("STATIC");assertThrows(org.springframework.web.server.ResponseStatusException.class,()->collector.collect(p.clusterId(),UUID.randomUUID(),request(KafkaExpansionWorkflow.Layout.CONTROLLER)));}
    @Test void duplicateCommonEvidenceCannotHideAFailedCheck()throws Exception{fixture();common.checks().add(new Check("C01","duplicate","COMMON","FAIL","ok","failed","",Instant.now(),"AGENT"));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->collector.collect(p.clusterId(),UUID.randomUUID(),request(KafkaExpansionWorkflow.Layout.CONTROLLER)));verifyNoInteractions(runtime,quorum);}
    @Test void systemJdkRequiresMatchingCandidateAndParticipantAgents()throws Exception{
 fixture();var profile=new HashMap<>(common.brokerPlan());profile.put("javaHome","/usr/lib/jvm/jdk-17");common=new Preview(common.previewId(),common.clusterId(),common.hostId(),common.contextHash(),common.checkedAt(),common.expiresAt(),common.status(),common.checks(),profile,false);tasks.findById(previewId).orElseThrow().setParameters(mapper.writeValueAsString(Map.of("readiness_request",mapper.writeValueAsString(profile))));
 assertThrows(org.springframework.web.server.ResponseStatusException.class,()->collector.collect(p.clusterId(),UUID.randomUUID(),request(KafkaExpansionWorkflow.Layout.SEPARATE)));
 hosts.findById(p.candidateHostId()).orElseThrow().setAgentVersion("test-addnode.8");assertThrows(org.springframework.web.server.ResponseStatusException.class,()->collector.collect(p.clusterId(),UUID.randomUUID(),request(KafkaExpansionWorkflow.Layout.SEPARATE)));
 for(var participant:p.participants())hosts.findById(participant.hostId()).orElseThrow().setAgentVersion("test-addnode.8");
 assertEquals("/usr/lib/jvm/jdk-17",collector.collect(p.clusterId(),UUID.randomUUID(),request(KafkaExpansionWorkflow.Layout.SEPARATE)).frozen().plan().javaHome());
 hosts.findById(p.participants().getFirst().hostId()).orElseThrow().setAgentVersion("test-addnode.7");assertThrows(org.springframework.web.server.ResponseStatusException.class,()->collector.collect(p.clusterId(),UUID.randomUUID(),request(KafkaExpansionWorkflow.Layout.CONTROLLER)));
 }
}
